package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0 // PIC 9(3) len=3 = 0
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxRec TaxRec

var taxFile *os.File
var taxReader *bufio.Reader

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// storePic keeps only low-order digits that fit: integer digits intDigits, scale 2
func storePic(v decimal.Decimal, intDigits int) decimal.Decimal {
	// v assumed already quantized to scale 2 (rounded or truncated)
	// keep low-order digits: modulo 10^(intDigits+2) on cents
	mod := pow10(intDigits + 2)
	// cents truncated toward zero
	cents := v.Shift(2).Truncate(0)
	neg := cents.IsNegative()
	if neg {
		cents = cents.Neg()
	}
	// cents >=0 now
	q := cents.QuoRem(decimal.NewFromInt(mod), nil)
	_ = q
	// use Mod
	m := cents.Mod(decimal.NewFromInt(mod))
	if neg {
		m = m.Neg()
	}
	return m.Shift(-2)
}

func formatEdited(v decimal.Decimal, picture string) string {
	// count integer digit slots and scale
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	// integer slots
	type slot struct {
		picIdx int
		kind   byte // 'Z' or '9'
	}
	var slots []slot
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			slots = append(slots, slot{i, c})
		}
	}
	n := len(slots)
	// quantize value to fracDigits by truncation toward zero (value already quantized)
	q := v.Truncate(int32(fracDigits))
	neg := q.IsNegative()
	aq := q.Abs()
	intPart := aq.IntPart()
	// fractional part
	fracPart := aq.Sub(decimal.NewFromInt(intPart)).Shift(int32(fracDigits)).Truncate(0).IntPart()
	if fracPart < 0 {
		fracPart = -fracPart
	}
	// drop high-order integer digits
	var mod int64 = 1
	for i := 0; i < n; i++ {
		mod *= 10
	}
	if n > 0 {
		intPart = intPart % mod
	}
	// digit string padded to n
	digits := fmt.Sprintf("%0*d", n, intPart)
	if len(digits) > n {
		digits = digits[len(digits)-n:]
	}
	// find first non-zero
	firstNZ := n
	for i := 0; i < n; i++ {
		if digits[i] != '0' {
			firstNZ = i
			break
		}
	}
	// build integer part output
	out := make([]byte, len(picture))
	// map slot index -> digit / space decision
	slotOut := make([]byte, n)
	for j := 0; j < n; j++ {
		if j < firstNZ {
			if slots[j].kind == 'Z' {
				slotOut[j] = ' '
			} else {
				slotOut[j] = digits[j] // '0'
			}
		} else {
			slotOut[j] = digits[j]
		}
	}
	// fill picture
	si := 0
	hasSig := false
	// we need to know for comma: if any significant digit to left
	// iterate over intPic positions left to right
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			b := slotOut[si]
			si++
			out[i] = b
			if b != ' ' {
				hasSig = true
			}
		} else if c == ',' {
			if hasSig {
				out[i] = ','
			} else {
				out[i] = ' '
			}
		} else if c == '.' {
			out[i] = '.'
		} else {
			out[i] = c
		}
	}
	if dotIdx >= 0 {
		out[dotIdx] = '.'
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)
		for i := 0; i < fracDigits; i++ {
			out[dotIdx+1+i] = fracStr[i]
		}
	}
	s := string(out)
	if neg {
		// place minus sign: replace last space before significant digit if possible
		// simple: replace rightmost space in integer part with '-'
		b := []byte(s)
		for i := dotIdx - 1; i >= 0; i-- {
			if b[i] == ' ' {
				// find position just left of number? COBOL would put '-' floating?
				// Use rightmost space adjacent to digits
				continue
			}
		}
		// fallback: prefix
		_ = b
	}
	return s
}

func parseIncome(field string) decimal.Decimal {
	// field is 8 chars digits only (implied decimal)
	s := strings.TrimSpace(field)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits? assume digits
	// handle possible sign? not expected
	neg := false
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		if strings.HasPrefix(s, "-") {
			neg = true
		}
		s = s[1:]
	}
	// remove any '.' if present (shouldn't be)
	s = strings.ReplaceAll(s, ".", "")
	s = strings.ReplaceAll(s, " ", "0")
	if s == "" {
		return decimal.NewFromInt(0)
	}
	var n int64
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			n = n*10 + int64(s[i]-'0')
		}
	}
	d := decimal.New(n, -2)
	if neg {
		d = d.Neg()
	}
	return d
}

func main() {
	MAINPARA()
}

func MAINPARA() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty?
		if os.IsNotExist(err) {
			taxFile = nil
			taxReader = bufio.NewReader(strings.NewReader(""))
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		taxReader = bufio.NewReader(taxFile)
		defer taxFile.Close()
	}
	if taxReader == nil {
		taxReader = bufio.NewReader(strings.NewReader(""))
	}
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if taxFile != nil {
		taxFile.Close()
		taxFile = nil
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	fmt.Fprint(os.Stdout, "TAXPAYERS: "+countStr+" TOTAL TAX: "+WsTotalEd+"\n")
}

func READPARA() {
	if taxReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := taxReader.ReadString('\n')
	if err != nil {
		// if we got data before EOF, process it
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// else fall through to process line, next read will be EOF
	} else {
		// strip trailing \n and \r only
		if strings.HasSuffix(line, "\n") {
			line = line[:len(line)-1]
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
		}
		parseTaxRec(line)
		return
	}
	// EOF with data
	if strings.HasSuffix(line, "\n") {
		line = line[:len(line)-1]
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
	} else {
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
	}
	// If line empty and err != nil, it was handled; otherwise parse
	if len(line) == 0 && err != nil {
		WsEofFlag = "Y"
		return
	}
	parseTaxRec(line)
	// Next read will hit EOF; but if err was EOF we need to remember?
	// We consumed the last line without newline; next call will return EOF.
	// To avoid losing, we can't set done now. However bufio will return EOF next time.
	// But we already got err==EOF; the next call will also EOF.
	// So just parse now.
	// Trick: if err != nil, we need to arrange that next READPARA returns EOF.
	// Since reader is at EOF, next call will do so. Good.
	_ = err
}

func parseTaxRec(line string) {
	// pad with spaces to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	taxRec.TrId = line[0:5]
	taxRec.TrIncome = parseIncome(line[5:13])
}

func PROCESSPARA() {
	limit1 := decimal.New(10000, 0)
	limit2 := decimal.New(40000, 0)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)
	_ = rate10
	// Use exact decimals for rates: 0.10 = 1/10
	r10 := decimal.New(1, -1)
	r20 := decimal.New(2, -1)
	r30 := decimal.New(3, -1)
	thousand := decimal.New(1000, 0)
	sevenThousand := decimal.New(7000, 0)
	tenThousand := decimal.New(10000, 0)
	fortyThousand := decimal.New(40000, 0)
	if taxRec.TrIncome.Cmp(limit1) <= 0 {
		v := taxRec.TrIncome.Mul(r10)
		v = v.Round(2)
		WsTax = storePic(v, 7)
	} else {
		if taxRec.TrIncome.Cmp(limit2) <= 0 {
			v := thousand.Add(taxRec.TrIncome.Sub(tenThousand).Mul(r20))
			v = v.Round(2)
			WsTax = storePic(v, 7)
		} else {
			v := sevenThousand.Add(taxRec.TrIncome.Sub(fortyThousand).Mul(r30))
			v = v.Round(2)
			WsTax = storePic(v, 7)
		}
	}
	_ = thousand
	_ = sevenThousand
	_ = rate20
	_ = rate30
	vnet := taxRec.TrIncome.Sub(WsTax).Truncate(2)
	WsNet = storePic(vnet, 7)
	WsTotalTax = storePic(WsTotalTax.Add(WsTax), 9)
	WsCount = (WsCount + 1) % 1000
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Fprint(os.Stdout, taxRec.TrId+" "+WsIncEd+" "+WsTaxEd+" "+WsNetEd+"\n")
	READPARA()
}

